var t=`0628-asida`;var n=`world-0628`;var s=`LY`;var a=`northern-africa`;var o=4;var r=49;var l={en:`Asida`,ua:`Асіда`};var u={en:`Asida is a Libya classic prepared with all-purpose flour, semolina flour. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Асіда, страва кухні країни Лівія зі складниками: пшеничне борошно універсальне, семоліна. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`water`,820,`ml`],[`table-salt`,4,`g`]]},{en:`Add flour to the hot water and beat continuously into a stiff, smooth paste; shape the asida mound with a damp spoon.`,ua:`Всипте борошно в гарячу воду й безперервно розмішуйте до густої однорідної маси; сформуйте асіду вологою ложкою.`,t:[`mixing`],m:20,i:[[`all-purpose-flour`,350,`g`],[`unsalted-butter`,50,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 18 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 18 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:18,i:[[`semolina-flour`,150,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`honey`,110,`g`],[`ghee`,45,`g`]]}];var d={slug:t,id:n,country:`LY`,region:a,servings:4,minutes:49,title:l,text:u,steps:g};export{s as country,d as default,n as id,r as minutes,a as region,o as servings,t as slug,g as steps,u as text,l as title};